function Point(x) {
  this.x = x;
  if (x < 0) {
    return { x: 0 };
  }
  if (x > 99) {
    return null;
  }
}

const a = new Point(5);
const b = new Point(-3);
const c = new Point(500);

console.log(a.x, b.x, c.x);
console.log(Object.getPrototypeOf(b) === Point.prototype, Object.getPrototypeOf(c) === Point.prototype);

try {
  console.log(Point(-1).x);
} catch (error) {
  console.log(error.name);
}
